<?php  namespace App\Providers;  use Bitfumes\Multiauth\Http\Middleware\redirectIfAuthenticatedAdmin; use Bitfumes\Multiauth\Http\Middleware\redirectIfNotWithRoleOfAdmin; use Illuminate\Support\Facades\Route; use Illuminate\Support\ServiceProvider;  class MultiauthServiceProvider extends ServiceProvider {     public function register(): void     {         $this->mergeConfigFrom(             base_path('vendor/bitfumes/laravel-multiauth/config/multiauth.php'),             'multiauth'         );     }    public function boot(): void     {         $this->loadViewsFrom(             base_path('vendor/bitfumes/laravel-multiauth/src/views'),             'multiauth'         );          $this->loadMiddleware();         $this->loadAdminRoutes();     }      protected function loadMiddleware(): void     {         $router = $this->app['router'];          $router->aliasMiddleware(             'admin',             redirectIfAuthenticatedAdmin::class         );          $router->aliasMiddleware(             'role',             redirectIfNotWithRoleOfAdmin::class         );     }    protected function loadAdminRoutes(): void     {         if ($this->app->routesAreCached()) {             return;         }          $prefix = config('multiauth.prefix', 'admin');         $customRoutes = base_path("routes/{$prefix}.php");          if (file_exists($customRoutes)) {             Route::middleware('web')                 ->prefix($prefix)                 ->group($customRoutes);              return;         }          Route::middleware('web')             ->prefix($prefix)             ->group(                 base_path('vendor/bitfumes/laravel-multiauth/src/routes/routes.php')             );     } }
